@@ -114,14 +114,14 @@ impl VulkanSubmissionMode {
     pub fn max_in_flight(self) -> usize {
         match self {
             Self::Synchronous => 1,
-            Self::Asynchronous => 3,
+            Self::Asynchronous => if cfg!(target_os = "macos") { 6 } else { 3 },
         }
     }
     fn command_slots(self) -> usize {
         // One acquire and one publish barrier per in-flight rendered frame.
         match self {
             Self::Synchronous => 1,
-            Self::Asynchronous => 6,
+            Self::Asynchronous => 2 * self.max_in_flight(),
         }
     }
 }
